187	/// Builds an intent whose declared binary slots are bound to the current
188	/// coordinator workflow. Callers recovering an old release source must pass
189	/// the current coordinator revision here, never substitute the source SHA.
190	///
191	/// Returns advisory diagnostics from derivation (e.g. an artifact owner selected
192	/// without its product) alongside the intent, for a caller to surface.
193	pub fn build_release_intent_with_artifacts<L: ProjectLocator, R: CommandRunner>(
194	    root: &Path,
195	    locator: &L,
196	    runner: &R,
197	    decision: &ReleaseDecisionV1,
198	    trust_profile: ExecutionTrustProfileV1,
199	    artifact_policy: ArtifactBuildPolicy,
200	) -> Result<(ReleaseIntentV1, Vec<callisto_model::Diagnostic>), GraphError> {
201	    let root = canonical_root(root)?;
202	    let workspace = Workspace::load(root.clone(), locator, runner)?;
203	    let source = observe_source(&workspace, trust_profile, ReleaseCheckout::Detached)?;
204	    let mut diagnostics = Vec::new();
205	    let intent = derive_release_intent(
206	        &workspace,
207	        decision,
208	        source.clone(),
209	        trust_profile,
210	        Some(&artifact_policy),
211	        GitRemoteRequirement::Required,
212	        &mut diagnostics,
213	    )?;
214	    if observe_source(&workspace, trust_profile, ReleaseCheckout::Detached)? != source {
215	        return Err(GraphError::ReleaseIntentStale {
216	            reason: StaleReason::source_identity_changed(),
217	        });
