329	/// The fixed and linked groups a release package belongs to, per config.
330	fn release_groups_of<R: callisto_model::CommandRunner, D: DependencyResolver>(
331	    workspace: &Workspace<'_, R, D>,
332	    id: &ReleasePackageId,
333	) -> Vec<(&'static str, callisto_model::GroupName)> {
334	    let Some(package) = workspace_package(workspace, id) else {
335	        return Vec::new();
336	    };
337	    let groups = &workspace.config.groups;
338	    let fixed = groups.fixed_of.iter().map(|(member, group)| ("fixed", member, group));
339	    let linked = groups.linked_of.iter().map(|(member, group)| ("linked", member, group));
340	    // `member` keys are already canonical (`GroupTable::resolve` resolved
341	    // them through `IdentityIndex::resolve`), so exact equality is correct
342	    // here -- `PackageId::matches` would treat a Bare member key as an
343	    // ecosystem wildcard and could match a same-named package elsewhere.
344	    fixed
345	        .chain(linked)
346	        .filter(|(_, member, _)| **member == package.id)
347	        .map(|(kind, _, group)| (kind, group.clone()))
348	        .collect()
349	}
