351	/// Verifies the release roster a merged release commit claims, against a
352	/// release-decision file committed alongside it at `decision_path`.
353	///
354	/// This is intentionally *not* a second computation of changeset, fixed-group,
355	/// linked-group, cascade, or pre-release-policy inclusion. `plan_version`
356	/// (via [`derive_release_decision`]) already computed that once, correctly,
357	/// when the release PR was generated -- and `callisto version --emit-decision`
358	/// commits its exact output alongside the manifest and changelog edits.
359	/// Re-deriving that policy a second time here, from raw git diffs, is exactly
360	/// the kind of duplicated logic that drifts: an earlier version of this
361	/// function did just that, understood only a direct changeset match, and
362	/// rejected every real release in this repository once a fixed-group cascade
363	/// (a case its reimplementation never learned) touched an unnamed sibling.
364	///
365	/// Instead, this function reads the committed decision back and confirms the
366	/// commit's actual diff matches it exactly -- no more, no less.
367	/// [`ReleaseDecisionV1`]'s own deserializer already rejects a decision whose
368	/// entries don't match its content digest, so a hand-edited or corrupted
369	/// decision file fails before this function's own diff cross-check runs.
370	///
371	/// The caller must check out the exact merge commit in detached HEAD state
372	/// before creating an intent. GitHub-specific PR/approval provenance belongs
373	/// in the workflow boundary; this graph function verifies the local,
374	/// provider-neutral commit delta only.
375	pub fn derive_release_commit_decision<R: CommandRunner, D: DependencyResolver>(
376	    workspace: &Workspace<'_, R, D>,
377	    release_commit: &CommitSha,
378	    decision_path: &std::path::Path,
379	) -> Result<ReleaseDecisionV1, GraphError> {
380	    let head_args = ["rev-parse", "HEAD"];
381	    let head = git_stdout(workspace.runner, &workspace.root, &head_args)?;
382	    let head =
383	        CommitSha::parse(&head).map_err(|source| command_malformed_output("git", &head_args, source.to_string()))?;
384	    if &head != release_commit {
385	        return Err(GraphError::ReleaseCommitVerificationFailed {
386	            commit: release_commit.clone(),
387	            reason: CommitVerificationFailure::HeadMismatch,
388	        });
389	    }
390	
391	    let parent_ref = format!("{}^", release_commit.as_str());
392	    let parent_args = ["rev-parse", parent_ref.as_str()];
393	    let parent = git_stdout(workspace.runner, &workspace.root, &parent_args)?;
394	    CommitSha::parse(&parent).map_err(|source| command_malformed_output("git", &parent_args, source.to_string()))?;
395	
396	    let diff_tree_args = [
397	        "diff-tree",
398	        "--no-commit-id",
399	        "--name-status",
400	        "-r",
401	        "--no-renames",
402	        parent.as_str(),
403	        release_commit.as_str(),
404	    ];
405	    let changed = git_stdout(workspace.runner, &workspace.root, &diff_tree_args)?;
406	    let changed = parse_name_status(&changed, &diff_tree_args)?;
407	
408	    // The decision must be freshly authored as part of *this* commit, not a
409	    // stale leftover an earlier release already committed and this one never
410	    // touched -- otherwise a commit that changes nothing real could still
411	    // carry forward a prior, unrelated decision's authority.
412	    let decision_path_str = normalized_git_path(decision_path)?;
413	    let decision_freshly_written = changed
414	        .iter()
415	        .any(|(status, path)| path == &decision_path_str && matches!(status.as_str(), "A" | "M"));
416	    if !decision_freshly_written {
417	        return Err(GraphError::ReleaseCommitVerificationFailed {
418	            commit: release_commit.clone(),
419	            reason: CommitVerificationFailure::DecisionNotWrittenByCommit,
420	        });
421	    }
422	
423	    // A cheap, independent sanity check that this commit is a real version
424	    // application and not just a hand-crafted decision file: some real
425	    // changeset was actually consumed. The decision's own entries, not this
426	    // changeset's content, remain the sole authority verified below.
427	    let changeset_dir = normalized_git_path(&workspace.config.changesets_dir)?;
428	    let consumed_a_changeset = changed
429	        .iter()
430	        .any(|(status, path)| status == "D" && is_changeset_path(path, &changeset_dir));
431	    if !consumed_a_changeset {
432	        return Err(GraphError::ReleaseCommitVerificationFailed {
433	            commit: release_commit.clone(),
434	            reason: CommitVerificationFailure::NoChangesetConsumed,
435	        });
436	    }
437	
438	    let decision_source = git_file(
439	        workspace.runner,
440	        &workspace.root,
441	        release_commit.as_str(),
442	        &decision_path_str,
443	    )?;
444	    let decision: ReleaseDecisionV1 =
445	        serde_json::from_str(&decision_source).map_err(|error| GraphError::ReleaseDecisionDecode {
446	            path: decision_path.to_path_buf(),
447	            message: error.to_string(),
448	        })?;
449	    let claimed = decision
450	        .entries
451	        .iter()
452	        .map(|entry| (entry.package.clone(), entry.target_version.clone()))
453	        .collect::<std::collections::BTreeMap<_, _>>();
454	
455	    let changed_paths = changed
456	        .iter()
457	        .filter_map(|(status, path)| matches!(status.as_str(), "A" | "M").then_some(path.as_str()))
458	        .collect::<std::collections::BTreeSet<_>>();
459	
460	    // Every canonical manifest path this workspace currently declares, in
461	    // the exact order `workspace.graph.packages()` and
462	    // `Package::canonical_manifests()` yield -- both are backed by ordered
463	    // (`BTreeMap`/`Vec`) storage with no interior mutation between calls, so
464	    // the second traversal below visits the same (package, manifest) pairs
465	    // in the same order. That lets it zip the batched `before`/`after`
466	    // results back on by position instead of re-keying by path, which would
467	    // misbehave if two packages ever declared an identical manifest path.
468	    let manifest_queries: Vec<(String, Ecosystem)> = workspace
469	        .graph
470	        .packages()
471	        .flat_map(Package::canonical_manifests)
472	        .map(|manifest| Ok((normalized_git_path(&manifest.path)?, manifest.ecosystem())))
473	        .collect::<Result<_, GraphError>>()?;
474	    let mut query_paths: Vec<&str> = manifest_queries.iter().map(|(path, _)| path.as_str()).collect();
475	    if manifest_queries
476	        .iter()
477	        .any(|(_, ecosystem)| *ecosystem == Ecosystem::Cargo)
478	        && !query_paths.contains(&"Cargo.toml")
479	    {
480	        query_paths.push("Cargo.toml");
481	    }
482	
483	    // Exactly two `git cat-file --batch` subprocess invocations total (one
484	    // per commit), regardless of how many canonical manifests the
485	    // workspace has -- replaces what was previously 2*N separate `git
486	    // show` spawns (one `manifest_version_at` call per manifest per
487	    // commit).
488	    let before_blobs = batch_manifest_blobs_at(workspace.runner, &workspace.root, &parent, &query_paths)?;
489	    let after_blobs =
490	        batch_manifest_blobs_at(workspace.runner, &workspace.root, release_commit.as_str(), &query_paths)?;
491	    let before_versions = resolve_batch_versions(before_blobs, &query_paths, &manifest_queries)?;
492	    let after_versions = resolve_batch_versions(after_blobs, &query_paths, &manifest_queries)?;
493	
494	    let mut observed = std::collections::BTreeSet::new();
495	    let mut manifest_index = 0usize;
496	    for package in workspace.graph.packages() {
497	        let package_ids = release_package_ids(&workspace.identity, package)?;
498	        let package_is_claimed = package_ids.iter().any(|id| claimed.contains_key(id));
499	        if package_is_claimed {
500	            let changelog = package.changelog.as_ref().ok_or(GraphError::ReleasePreconditionUnmet {
501	                requirement: ReleasePreconditionRequirement::ChangelogConfigured,
502	            })?;
503	            let changelog = normalized_git_path(changelog)?;
504	            if !changed_paths.contains(changelog.as_str()) {
505	                return Err(GraphError::ReleaseCommitVerificationFailed {
506	                    commit: release_commit.clone(),
507	                    reason: CommitVerificationFailure::ChangelogNotTouched,
508	                });
509	            }
510	        }
511	        for id in package_ids {
512	            let before = &before_versions[manifest_index];
513	            let after = &after_versions[manifest_index];
514	            manifest_index += 1;
515	            let changed_version = before.version != after.version;
516	            match claimed.get(&id) {
517	                Some(target_version) => {
518	                    if !changed_paths.contains(after.authority.to_string_lossy().as_ref()) {
519	                        return Err(GraphError::ReleaseCommitVerificationFailed {
520	                            commit: release_commit.clone(),
521	                            reason: CommitVerificationFailure::ManifestNotInDiff,
522	                        });
523	                    }
524	                    if !changed_version || &after.version != target_version {
525	                        return Err(GraphError::ReleaseCommitVerificationFailed {
526	                            commit: release_commit.clone(),
527	                            reason: CommitVerificationFailure::ManifestVersionMismatch,
528	                        });
529	                    }
530	                    observed.insert(id);
531	                }
532	                None => {
533	                    if changed_version {
534	                        // A changed version the committed decision never
535	                        // claimed is not this commit's authority -- fail
536	                        // closed rather than trust a partial match.
537	                        return Err(GraphError::ReleaseCommitVerificationFailed {
538	                            commit: release_commit.clone(),
539	                            reason: CommitVerificationFailure::UnclaimedVersionChange,
540	                        });
541	                    }
542	                }
543	            }
544	        }
545	    }
546	    if observed.len() != claimed.len() {
547	        return Err(GraphError::ReleaseCommitVerificationFailed {
548	            commit: release_commit.clone(),
549	            reason: CommitVerificationFailure::ClaimedPackageNotObserved,
550	        });
551	    }
552	
553	    Ok(decision)
554	}
