556	fn is_changeset_path(path: &str, changeset_dir: &str) -> bool {
557	    let Some(file_name) = path.strip_prefix(changeset_dir).and_then(|path| {
558	        if changeset_dir.is_empty() {
559	            Some(path)
560	        } else {
561	            path.strip_prefix('/')
562	        }
563	    }) else {
564	        return false;
565	    };
566	
567	    !file_name.contains('/') && file_name.ends_with(".md") && file_name != "README.md"
568	}
