602	fn parse_name_status(output: &str, args: &[&str]) -> Result<Vec<(String, String)>, GraphError> {
603	    output
604	        .lines()
605	        .map(|line| {
606	            let (status, path) = line.split_once('\t').ok_or_else(|| {
607	                command_malformed_output(
608	                    "git",
609	                    args,
610	                    format!("name-status line missing a tab separator: `{line}`"),
611	                )
612	            })?;
613	            if !matches!(status, "A" | "M" | "D") || path.is_empty() || path.contains('\0') {
614	                return Err(command_malformed_output(
615	                    "git",
616	                    args,
617	                    format!("name-status reported an unexpected status/path: `{status}` `{path}`"),
618	                ));
619	            }
620	            Ok((status.to_string(), path.to_string()))
621	        })
622	        .collect()
623	}
