683	/// One object's content as reported by `git cat-file --batch`, for a single
684	/// requested `<commit>:<path>`.
685	enum BatchBlob {
686	    /// The path resolved to a blob at the queried commit; this is its raw
687	    /// content.
688	    Blob(String),
689	    /// The path did not exist at the queried commit -- e.g. a package's
690	    /// manifest that was only added later, so it has no blob yet at an
691	    /// earlier `parent` commit.
692	    Missing,
693	}
694	
695	/// Issues exactly one `git cat-file --batch` invocation requesting every
696	/// path in `paths` as `<commit>:<path>`, and returns each result in the
697	/// same order as `paths`.
698	///
699	/// `git cat-file --batch` reads one object identifier per line from stdin
700	/// and, for each, writes to stdout either:
701	///
702	/// ```text
703	/// <sha> SP <type> SP <size> LF
704	/// <content: exactly `size` bytes> LF
705	/// ```
706	///
707	/// or, if the object doesn't exist:
708	///
709	/// ```text
710	/// <object> SP missing LF
711	/// ```
712	///
713	/// (git also reports `<object> SP ambiguous LF` for a ref that resolves to
714	/// more than one object; `<commit>:<path>` syntax should never be
715	/// ambiguous, but it's checked for explicitly below rather than silently
716	/// falling through to the blob-header parse.)
717	///
718	/// This lets every canonical manifest's content at one commit be fetched in
719	/// a single subprocess round trip instead of one `git show` per manifest.
720	///
721	/// Parsing here is deliberately defensive rather than permissive: this
722	/// feeds [`derive_release_commit_decision`]'s trust-boundary comparison, so
723	/// any framing ambiguity -- an unrecognized header shape, a declared `size`
724	/// that doesn't fit the remaining output, a missing separator byte right
725	/// after the declared content length, a non-`blob` object type, or a
726	/// leftover/truncated tail once every requested path has been accounted
727	/// for -- fails the whole batch closed rather than guessing. Each expected
728	/// response is also matched against its exact requested object string
729	/// (rather than a generic "ends with ` missing`" pattern), so a manifest
730	/// path that happened to contain a space or colon can't be misread as a
731	/// different response shape. Silently misattributing one manifest's
732	/// content to a different path because an undetected desync shifted every
733	/// later offset would be a far worse failure mode than an outright
734	/// rejection.
735	fn batch_manifest_blobs_at<R: CommandRunner>(
736	    runner: &R,
737	    root: &std::path::Path,
738	    commit: &str,
739	    paths: &[&str],
740	) -> Result<Vec<BatchBlob>, GraphError> {
741	    if paths.is_empty() {
742	        return Ok(Vec::new());
743	    }
744	
745	    const BATCH_ARGS: [&str; 2] = ["cat-file", "--batch"];
746	
747	    let mut stdin = String::new();
748	    let objects: Vec<String> = paths
749	        .iter()
750	        .map(|path| {
751	            let object = format!("{commit}:{path}");
752	            stdin.push_str(&object);
753	            stdin.push('\n');
754	            object
755	        })
756	        .collect();
757	
758	    let output = runner.run_with_stdin("git", &BATCH_ARGS, root, stdin.as_bytes())?;
759	    if !output.success() {
760	        return Err(command_non_zero_exit("git", &BATCH_ARGS, &output));
761	    }
762	
763	    let mut rest = output.stdout.as_str();
764	    let mut results = Vec::with_capacity(objects.len());
765	    for object in &objects {
766	        let (header, after_header) = rest.split_once('\n').ok_or_else(|| {
767	            command_malformed_output(
768	                "git",
769	                &BATCH_ARGS,
770	                format!("truncated response: missing header line for `{object}`"),
771	            )
772	        })?;
773	
774	        if header == format!("{object} missing") {
775	            results.push(BatchBlob::Missing);
776	            rest = after_header;
777	            continue;
778	        }
779	        if header == format!("{object} ambiguous") {
780	            return Err(command_malformed_output(
781	                "git",
782	                &BATCH_ARGS,
783	                format!("object `{object}` is ambiguous"),
784	            ));
785	        }
786	
787	        let mut fields = header.split(' ');
788	        let sha = fields.next().ok_or_else(|| {
789	            command_malformed_output(
790	                "git",
791	                &BATCH_ARGS,
792	                format!("header for `{object}` is missing its sha field: `{header}`"),
793	            )
794	        })?;
795	        let object_type = fields.next().ok_or_else(|| {
796	            command_malformed_output(
797	                "git",
798	                &BATCH_ARGS,
799	                format!("header for `{object}` is missing its type field: `{header}`"),
800	            )
801	        })?;
802	        let size_field = fields.next().ok_or_else(|| {
803	            command_malformed_output(
804	                "git",
805	                &BATCH_ARGS,
806	                format!("header for `{object}` is missing its size field: `{header}`"),
807	            )
808	        })?;
809	        if fields.next().is_some() {
810	            // A well-formed header has exactly three space-separated
811	            // fields; anything else is not a shape this parser understands.
812	            return Err(command_malformed_output(
813	                "git",
814	                &BATCH_ARGS,
815	                format!("header for `{object}` has more than three fields: `{header}`"),
816	            ));
817	        }
818	        if sha.is_empty() || !sha.chars().all(|c| c.is_ascii_hexdigit()) {
819	            return Err(command_malformed_output(
820	                "git",
821	                &BATCH_ARGS,
822	                format!("header for `{object}` reports a non-hex sha: `{sha}`"),
823	            ));
824	        }
825	        if object_type != "blob" {
826	            // Every path requested here is a canonical manifest file, so a
827	            // resolved object must be a blob; a tree/commit/tag response
828	            // means the path resolved to something else entirely.
829	            return Err(command_malformed_output(
830	                "git",
831	                &BATCH_ARGS,
832	                format!("object `{object}` resolved to a `{object_type}`, not a blob"),
833	            ));
834	        }
835	        let size: usize = size_field.parse().map_err(|parse_error| {
836	            command_malformed_output(
837	                "git",
838	                &BATCH_ARGS,
839	                format!("header for `{object}` has a non-numeric size `{size_field}`: {parse_error}"),
840	            )
841	        })?;
842	
843	        if size > after_header.len() {
844	            return Err(command_malformed_output(
845	                "git",
846	                &BATCH_ARGS,
847	                format!("object `{object}` declares size {size}, exceeding the remaining response"),
848	            ));
849	        }
850	        // `.get(..size)` (byte-indexed) rather than raw slicing: if `size`
851	        // doesn't land on a UTF-8 char boundary this fails closed instead
852	        // of panicking.
853	        let content = after_header.get(..size).ok_or_else(|| {
854	            command_malformed_output(
855	                "git",
856	                &BATCH_ARGS,
857	                format!("object `{object}` declares size {size} that does not land on a UTF-8 boundary"),
858	            )
859	        })?;
860	        let remainder = &after_header[size..];
861	        // The protocol always emits exactly one LF right after the
862	        // content, separate from the content itself. Requiring it here
863	        // catches a desynced `size` (from an earlier, unexpectedly
864	        // reencoded entry) as an explicit error instead of silently
865	        // parsing the wrong bytes as this entry's content.
866	        if remainder.as_bytes().first() != Some(&b'\n') {
867	            return Err(command_malformed_output(
868	                "git",
869	                &BATCH_ARGS,
870	                format!("object `{object}` content is not followed by the expected newline separator"),
871	            ));
872	        }
873	        results.push(BatchBlob::Blob(content.to_string()));
874	        rest = &remainder[1..];
875	    }
876	
877	    if !rest.is_empty() {
878	        // More output than the requested objects account for -- either an
879	        // extra unexpected reply or a framing desync earlier in the
880	        // stream. Either way, fail closed rather than ignore it.
881	        return Err(command_malformed_output(
882	            "git",
883	            &BATCH_ARGS,
884	            "response contained more data than the requested objects account for",
885	        ));
886	    }
887	
888	    Ok(results)
889	}
