891	fn resolve_batch_versions(
892	    blobs: Vec<BatchBlob>,
893	    paths: &[&str],
894	    queries: &[(String, Ecosystem)],
895	) -> Result<Vec<callisto_manifests::EffectiveManifestVersion>, GraphError> {
896	    let sources: std::collections::BTreeMap<_, _> = paths.iter().copied().zip(blobs).collect();
897	    let cargo_workspace = match sources.get("Cargo.toml") {
898	        Some(BatchBlob::Blob(source)) => Some((std::path::Path::new("Cargo.toml"), source.as_str())),
899	        _ => None,
900	    };
901	    queries
902	        .iter()
903	        .map(|(path, ecosystem)| {
904	            let Some(BatchBlob::Blob(source)) = sources.get(path.as_str()) else {
905	                return Err(command_malformed_output(
906	                    "git",
907	                    &["cat-file", "--batch"],
908	                    format!("canonical manifest `{path}` was reported missing at the queried commit"),
909	                ));
910	            };
911	            let format = ecosystem
912	                .canonical_manifest_format()
913	                .ok_or_else(|| GraphError::ReleaseInvariant {
914	                    detail: format!("canonical manifest `{path}` has no canonical manifest format"),
915	                })?;
916	            callisto_manifests::read_effective_version(format, source, std::path::Path::new(path), cargo_workspace)
917	                .map_err(historical_manifest_error)?
918	                .ok_or_else(|| {
919	                    command_malformed_output(
920	                        "git",
921	                        &["cat-file", "--batch"],
922	                        format!("manifest `{path}` has no effective declared version"),
923	                    )
924	                })
925	        })
926	        .collect()
927	}
