929	fn reason_from_bump(
930	    reason: Option<&BumpReason>,
931	    package_ids: &std::collections::BTreeMap<callisto_model::PackageId, Vec<ReleasePackageId>>,
932	) -> Result<ReleaseInclusionReason, GraphError> {
933	    match reason {
934	        Some(BumpReason::Changeset { .. }) | None => Ok(ReleaseInclusionReason::Changeset),
935	        Some(BumpReason::Inference { .. }) => Ok(ReleaseInclusionReason::Inference),
936	        Some(BumpReason::LinkedGroupUnion { group }) => Ok(ReleaseInclusionReason::LinkedGroup {
937	            group_id: group.to_string(),
938	        }),
939	        Some(BumpReason::FixedGroupUnion { group } | BumpReason::NewGroupMember { group }) => {
940	            Ok(ReleaseInclusionReason::FixedGroup {
941	                group_id: group.to_string(),
942	            })
943	        }
944	        Some(BumpReason::PreRelease { tag }) => Ok(ReleaseInclusionReason::PreReleasePolicy { policy_id: tag.clone() }),
945	        Some(BumpReason::Cascade { via, dep_kind, .. }) => {
946	            // `package_ids` is derived from the same workspace graph `via`
947	            // was resolved against, so a miss (or a non-unique release
948	            // identity) here means that pairing broke, not that this is a
949	            // recoverable operator condition.
950	            let source = package_ids
951	                .get(via)
952	                .and_then(|ids| (ids.len() == 1).then(|| ids[0].clone()))
953	                .ok_or_else(|| GraphError::ReleaseInvariant {
954	                    detail: format!(
955	                        "cascade source package `{}` has no unique release package id",
956	                        via.display_name()
957	                    ),
958	                })?;
959	            Ok(ReleaseInclusionReason::Cascade {
960	                from: source,
961	                edge_kind: format!("{dep_kind:?}"),
962	            })
963	        }
964	        Some(BumpReason::PeerEscalation { via, .. }) => {
965	            let source = package_ids
966	                .get(via)
967	                .and_then(|ids| (ids.len() == 1).then(|| ids[0].clone()))
968	                .ok_or_else(|| GraphError::ReleaseInvariant {
969	                    detail: format!(
970	                        "peer-escalation source package `{}` has no unique release package id",
971	                        via.display_name()
972	                    ),
973	                })?;
974	            Ok(ReleaseInclusionReason::Cascade {
975	                from: source,
976	                edge_kind: "peer".to_string(),
977	            })
978	        }
979	        Some(_) => Err(GraphError::UnsupportedRelease {
980	            feature: UnsupportedReleaseFeature::BumpReason,
981	        }),
982	    }
983	}
