1205	    /// replaced 2*N `git show` spawns with 2 total, not N-scaled batches.
1206	    struct CountingBatchRunner {
1207	        release_commit: String,
1208	        parent: String,
1209	        decision_json: String,
1210	        name_status: String,
1211	        /// (commit, path) -> blob content; a path/commit pair with no entry
