1213	        /// --batch` behavior for a path that doesn't exist at that commit.
1214	        blobs: std::collections::BTreeMap<(String, String), String>,
1215	        run_calls: std::sync::Mutex<Vec<(String, Vec<String>)>>,
1216	        batch_calls: std::sync::Mutex<u32>,
1217	    }
