1223	            args: &[&str],
1224	            _cwd: &std::path::Path,
1225	        ) -> Result<callisto_model::CommandOutput, callisto_model::CommandError> {
1226	            self.run_calls
1227	                .lock()
1228	                .unwrap()
1229	                .push((program.to_string(), args.iter().map(|s| s.to_string()).collect()));
1230	
1231	            let ok = |stdout: String| {
1232	                Ok(callisto_model::CommandOutput {
1233	                    exit_code: Some(0),
1234	                    stdout,
1235	                    stderr: String::new(),
1236	                })
1237	            };
1238	            let rev_parse_parent = format!("{}^", self.release_commit);
1239	            let decision_object = format!("{}:.callisto/release-decision.json", self.release_commit);
1240	            if args.first().copied() == Some("rev-parse") && args.get(1).copied() == Some("HEAD") {
1241	                return ok(self.release_commit.clone());
1242	            }
1243	            if args.first().copied() == Some("rev-parse") && args.get(1).copied() == Some(rev_parse_parent.as_str()) {
1244	                return ok(self.parent.clone());
1245	            }
1246	            if args.first().copied() == Some("diff-tree") {
1247	                return ok(self.name_status.clone());
1248	            }
1249	            if args.first().copied() == Some("show") && args.get(1).copied() == Some(decision_object.as_str()) {
1250	                return ok(self.decision_json.clone());
1251	            }
1252	            panic!("unexpected `{program} {args:?}` in CountingBatchRunner::run");
1253	        }
