456	                if let Some((owner_id, _)) = selected
457	                    .iter()
458	                    .find(|(_, (pkg, _))| workspace.identity.identifies(&artifact.package, &pkg.id))
459	                {
460	                    diagnostics.push(unreleased_product_artifact_diagnostic(
461	                        &product.package,
462	                        artifact,
463	                        owner_id,
464	                    ));
465	                }
466	            }
467	        }
468	        for (id, (package, _)) in &selected {
469	            if !matches_product(package) {
470	                continue;
471	            }
472	            let forge = forge_by_package.get(id).ok_or_else(|| GraphError::ReleaseInvariant {
473	                detail: format!("product package `{id}` has no forge release operation"),
474	            })?;
475	            let (tag, prerelease) = match prepared.get(forge) {
476	                Some(PreparedOperation::ForgeRelease(prepared_forge)) => {
477	                    (prepared_forge.tag.clone(), prepared_forge.prerelease)
478	                }
479	                _ => {
480	                    return Err(GraphError::ReleaseInvariant {
481	                        detail: format!("product forge release `{forge:?}` is not prepared"),
482	                    })
483	                }
484	            };
485	            for artifact in &product.artifacts {
486	                // The slot names the package whose build produced the bytes, which
487	                // need not be the product -- a plugin can ship on the product's
488	                // release. Every slot still attaches to the product's one release.
489	                let (owner_id, owner_version) = selected
490	                    .iter()
491	                    .find(|(_, (pkg, _))| workspace.identity.identifies(&artifact.package, &pkg.id))
492	                    .map(|(candidate, (_, owner_version))| (candidate.clone(), owner_version.clone()))
493	                    .ok_or_else(|| GraphError::ReleaseArtifactOwnerNotReleased {
494	                        asset: artifact.asset_name.clone(),
495	                        package: artifact.package.to_string(),
496	                    })?;
497	                let slot = ArtifactSlotId::new(
498	                    owner_id.clone(),
499	                    owner_version.clone(),
500	                    &artifact.target,
501	                    artifact.asset_name.clone(),
502	                    policy.repository.clone(),
503	                    policy.workflow_path.clone(),
504	                    policy.workflow_commit.clone(),
505	                )
506	                .map_err(|error| GraphError::ReleaseInvariant {
507	                    detail: format!("invalid configured artifact slot: {error}"),
508	                })?;
509	                let operation = ReleaseOperation::artifact_upload(slot.clone(), vec![forge.clone()])?;
510	                prepared.insert(
511	                    operation.id().clone(),
512	                    PreparedOperation::ArtifactUpload(ArtifactUploadOperation {
513	                        slot: slot.clone(),
514	                        tag: tag.clone(),
515	                        prerelease,
516	                    }),
517	                );
518	                // Keyed by the product's id: a plugin-built asset must still gate the product's own forge-publish.
519	                uploads_by_package
520	                    .entry(id.clone())
521	                    .or_default()
522	                    .push(operation.id().clone());
523	                operations.insert(operation.id().clone(), operation);
524	                artifact_slots.push(slot);
525	            }
526	        }
527	    }
528	
529	    // Publishing is the last forge step: a GitHub Release is only complete
530	    // once every asset it carries has been uploaded to it as a draft.
531	    for (id, (_, version)) in &selected {
532	        let Some(forge) = forge_by_package.get(id) else {
533	            continue;
534	        };
535	        let mut prerequisites = vec![forge.clone()];
536	        prerequisites.extend(uploads_by_package.get(id).into_iter().flatten().cloned());
537	        let operation = ReleaseOperation::forge_publish(id.clone(), version.clone(), prerequisites)?;
538	        let tag = match prepared.get(forge) {
539	            Some(PreparedOperation::ForgeRelease(prepared_forge)) => prepared_forge.tag.clone(),
540	            _ => {
541	                return Err(GraphError::ReleaseInvariant {
542	                    detail: format!("forge publish `{:?}` has no prepared draft release", operation.id()),
543	                })
544	            }
545	        };
546	        prepared.insert(
547	            operation.id().clone(),
548	            PreparedOperation::ForgePublish(ForgePublishOperation {
549	                tag,
550	                prerelease: version.is_prerelease(),
551	            }),
552	        );
553	        operations.insert(operation.id().clone(), operation);
554	    }
555	
556	    Ok((
557	        ReleaseInputSnapshotV1::new(source, package_inputs)?,
558	        canonical_operation_order(operations)?,
559	        prepared,
560	        git_remote,
561	        artifact_slots,
562	    ))
563	}
