565	/// Every unreleased, publishable workspace package a selected package reaches
566	/// through a runtime, optional, or peer edge must be selected with it, or the
567	/// selected package would publish pointing at a version that does not exist.
568	/// Standalone npm platform packages are one case of this.
569	fn require_dependencies_selected<R: CommandRunner, D: DependencyResolver>(
570	    workspace: &Workspace<'_, R, D>,
571	    selected: &BTreeMap<ReleasePackageId, (&callisto_model::Package, Version)>,
572	    package_ids: &BTreeMap<callisto_model::PackageId, Vec<ReleasePackageId>>,
573	) -> Result<(), GraphError> {
574	    let mut base_versions = None;
575	    for (package, _) in selected.values() {
576	        for edge in workspace.graph.dependencies_of(&package.id) {
577	            if !matches!(edge.kind, DepKind::Runtime | DepKind::Optional | DepKind::Peer)
578	                || package_ids.contains_key(&edge.to)
579	            {
580	                continue;
581	            }
582	            let Some(dependency) = workspace
583	                .graph
584	                .packages()
585	                .find(|candidate| candidate.id == edge.to && has_dispatchable_target(candidate))
586	            else {
587	                continue;
588	            };
589	            if base_versions.is_none() {
590	                base_versions = Some(workspace.base_versions()?);
591	            }
592	            let tags = workspace.tags()?;
593	            let released = base_versions
594	                .as_ref()
595	                .and_then(|versions| versions.get(&dependency.id))
596	                .is_some_and(|current| version_is_tagged(tags, &dependency.id, current));
597	            if !released {
598	                let id = crate::commands::release_decision::release_package_ids(&workspace.identity, dependency)?
599	                    .into_iter()
600	                    .next()
601	                    .ok_or_else(|| GraphError::ReleaseInvariant {
602	                        detail: format!("package `{}` has no release identity", dependency.id.display_name()),
603	                    })?;
604	                return Err(GraphError::ReleaseSelectionInvalid {
605	                    package: id,
606	                    reason: ReleaseSelectionInvalidReason::DependencyNotSelected,
607	                });
608	            }
609	        }
610	    }
611	    Ok(())
612	}
