614	/// A configured product package must exist and publish to github-release; otherwise
615	/// derivation would silently yield zero artifact slots.
616	fn require_product_package_publishes_to_forge<R: CommandRunner, D: DependencyResolver>(
617	    workspace: &Workspace<'_, R, D>,
618	    product: &callisto_model::PackageId,
619	) -> Result<(), GraphError> {
620	    let mut found = false;
621	    for package in workspace.graph.packages() {
622	        if !workspace.identity.identifies(product, &package.id) {
623	            continue;
624	        }
625	        found = true;
626	        if package
627	            .publish_to
628	            .iter()
629	            .any(|target| matches!(target, PublishTarget::GitHubRelease))
630	        {
631	            return Ok(());
632	        }
633	    }
634	    let detail = if found {
635	        format!("product-package `{product}` does not publish to github-release")
636	    } else {
637	        format!("product-package `{product}` is not a package in this workspace")
638	    };
639	    Err(crate::error::ConfigError::InvalidProductRelease { detail }.into())
640	}
