662	fn package_fingerprint<R: CommandRunner, D: DependencyResolver>(
663	    workspace: &Workspace<'_, R, D>,
664	    id: &ReleasePackageId,
665	    package: &callisto_model::Package,
666	    version: &Version,
667	    git_remote: Option<&PreparedGitRemote>,
668	) -> Result<SemanticInputDigest, GraphError> {
669	    let mut transcript = CanonicalTranscript::semantic_input_v1();
670	    transcript.push_str("package.id", &id.to_string());
671	    transcript.push_str("package.version", version.render());
672	    for manifest in &package.manifests {
673	        let path = workspace.root.join(&manifest.path);
674	        let bytes = std::fs::read(&path).map_err(|error| GraphError::ReleaseInputRead {
675	            path: manifest.path.clone(),
676	            message: error.to_string(),
677	        })?;
678	        transcript.push_str("manifest.path", &manifest.path.display().to_string());
679	        transcript.push_str("manifest.bytes", digest_bytes("manifest", &bytes).as_str());
680	        transcript.push_str("manifest.role", &manifest_role_text(&manifest.role));
681	        transcript.push_str("manifest.format", manifest.format.ecosystem().prefix());
682	    }
683	    transcript.push_str("package.trigger", release_trigger_text(package.release_trigger));
684	    transcript.push_str(
685	        "package.tag",
686	        &package
687	            .tag_template
688	            .as_ref()
689	            .map_or_else(|| "default".to_string(), |tag| tag.as_str()),
690	    );
691	    let npm_name = workspace
692	        .identity
693	        .native_name(&package.id, callisto_model::Ecosystem::Npm)
694	        .unwrap_or(package.id.name());
695	    for target in &package.publish_to {
696	        transcript.push_str(
697	            "package.target",
698	            target_fingerprint(workspace, &package.id, npm_name, target)?.as_str(),
699	        );
700	    }
701	    if let Some(remote) = git_remote {
702	        transcript.push_str("package.gitRemote", remote.identity.as_str());
703	    }
704	    Ok(SemanticInputDigest::from_transcript(&transcript))
705	}
