733	pub(crate) fn canonical_operation_order(
734	    operations: BTreeMap<ReleaseOperationId, ReleaseOperation>,
735	) -> Result<Vec<ReleaseOperation>, GraphError> {
736	    let mut remaining: BTreeMap<_, usize> = operations
737	        .iter()
738	        .map(|(id, operation)| (id.clone(), operation.prerequisites().len()))
739	        .collect();
740	    let mut dependents = BTreeMap::<ReleaseOperationId, Vec<ReleaseOperationId>>::new();
741	    for (id, operation) in &operations {
742	        for prerequisite in operation.prerequisites() {
743	            dependents.entry(prerequisite.clone()).or_default().push(id.clone());
744	        }
745	    }
746	    let mut ready: BTreeSet<_> = remaining
747	        .iter()
748	        .filter_map(|(id, count)| (*count == 0).then_some(id.clone()))
749	        .collect();
750	    let mut ordered = Vec::with_capacity(operations.len());
751	    while let Some(id) = ready.pop_first() {
752	        ordered.push(operations.get(&id).expect("known operation").clone());
753	        for dependent in dependents.get(&id).into_iter().flatten() {
754	            let count = remaining.get_mut(dependent).expect("known operation");
755	            *count -= 1;
756	            if *count == 0 {
757	                ready.insert(dependent.clone());
758	            }
759	        }
760	    }
761	    if ordered.len() != operations.len() {
762	        return Err(GraphError::ReleaseInvariant {
763	            detail: "release operation DAG contains a cycle: topological sort could not order every operation"
764	                .to_string(),
765	        });
766	    }
767	    Ok(ordered)
768	}
