770	fn digest_bytes(tag: &str, bytes: &[u8]) -> SemanticInputDigest {
771	    let mut transcript = CanonicalTranscript::semantic_input_v1();
772	    transcript.push_bytes(tag, bytes);
773	    SemanticInputDigest::from_transcript(&transcript)
774	}
