776	fn target_fingerprint<R: CommandRunner, D: DependencyResolver>(
777	    workspace: &Workspace<'_, R, D>,
778	    package: &callisto_model::PackageId,
779	    npm_name: &str,
780	    target: &PublishTarget,
781	) -> Result<SemanticInputDigest, GraphError> {
782	    let mut transcript = CanonicalTranscript::semantic_input_v1();
783	    // Single source of truth for the "kind" string, shared with
784	    // `PublishTarget::config_str`'s other diagnostic/config-parsing callers
785	    // instead of re-hardcoding these per-variant literals here too.
786	    transcript.push_str("target.kind", target.config_str());
787	    match target {
788	        PublishTarget::GitHubRelease | PublishTarget::None => {}
789	        PublishTarget::CratesIo => {
790	            push_registry_binding(
791	                &mut transcript,
792	                prepared_registry_binding(workspace, target, package)?.identity,
793	            )?;
794	        }
795	        PublishTarget::Npm { access, .. } => {
796	            push_registry_binding(
797	                &mut transcript,
798	                prepared_registry_binding(workspace, target, package)?.identity,
799	            )?;
800	            transcript.push_str(
801	                "target.access",
802	                match npm_default_access(npm_name, *access) {
803	                    Some(callisto_model::NpmAccess::Public) => "public",
804	                    Some(callisto_model::NpmAccess::Restricted) => "restricted",
805	                    None => "default",
806	                },
807	            );
808	        }
809	        PublishTarget::Pypi { .. } | PublishTarget::NuGet { .. } => {
810	            push_registry_binding(
811	                &mut transcript,
812	                prepared_registry_binding(workspace, target, package)?.identity,
813	            )?;
814	        }
815	        #[allow(unreachable_patterns)]
816	        _ => {
817	            return Err(GraphError::UnsupportedRelease {
818	                feature: UnsupportedReleaseFeature::PublishTarget,
819	            })
820	        }
821	    }
822	    Ok(SemanticInputDigest::from_transcript(&transcript))
823	}
