825	fn push_registry_binding(
826	    transcript: &mut CanonicalTranscript,
827	    fingerprint: RegistryBindingDigest,
828	) -> Result<(), GraphError> {
829	    transcript.push_str("target.registry", fingerprint.as_str());
830	    Ok(())
831	}
