1	//! The release provider port.
2	//!
3	//! Every remote fact and every remote effect in the release path goes through
4	//! one of these providers. The executor talks only to [`ReleaseProviderSet`],
5	//! so an in-memory set can drive it without a real registry, remote, or forge;
6	//! [`super::ValidatedReleaseIntent`] supplies the production implementation.
7	
8	use std::path::{Path, PathBuf};
9	
10	use callisto_model::{
11	    AbsentProof, ApplyPermit, ArtifactSlotId, CommandRunner, CommitSha, ExactEvidence, NpmAccess,
12	    ProviderObservationV1, ReleaseIntentV1, ReleaseOperationId, TagName, Version,
13	};
14	
15	use crate::error::{ReleasePreconditionRequirement, RemoteConflict};
16	use crate::GraphError;
17	
18	use super::binding::{recheck_git_remote, PreparedGitRemote, PreparedRegistryBinding};
19	use super::release_artifacts::VerifiedArtifactManifest;
20	
21	pub(crate) mod artifact;
22	pub(crate) mod forge;
23	pub(crate) mod http;
24	pub(crate) mod policy;
25	pub(crate) mod registry;
26	pub(crate) mod tag;
27	
28	/// The captured provider fixtures, and the loopback HTTP server the forge
29	/// tests run against. Shared verbatim with the CLI end-to-end harness so both
30	/// are held to the same captured bytes.
31	#[cfg(test)]
32	#[path = "../../../../../../testing/loopback_http.rs"]
33	pub(crate) mod loopback;
34	
35	/// The invocation data for one effect. This is deliberately graph-private:
36	/// callers can inspect the serializable intent, but cannot substitute a new
37	/// endpoint, tag target, or package directory at execution time.
38	#[derive(Debug)]
39	pub(crate) enum PreparedOperation {
40	    RegistryPublish(RegistryPublishOperation),
41	    Tag(TagOperation),
42	    ForgeRelease(ForgeReleaseOperation),
43	    ArtifactUpload(ArtifactUploadOperation),
44	    ForgePublish(ForgePublishOperation),
45	}
46	
47	#[derive(Debug)]
48	pub(crate) struct RegistryPublishOperation {
49	    pub(crate) package_dir: PathBuf,
50	    pub(crate) package_name: String,
51	    pub(crate) version: Version,
52	    pub(crate) registry: PreparedRegistryBinding,
53	    pub(crate) npm_access: Option<NpmAccess>,
54	    pub(crate) npm_tag: Option<String>,
55	    /// Publish `package_dir` by path rather than selecting a workspace member by name.
56	    pub(crate) by_directory: bool,
57	}
58	
59	#[derive(Debug)]
60	pub(crate) struct TagOperation {
61	    pub(crate) name: TagName,
62	    pub(crate) target: CommitSha,
63	    pub(crate) annotation: String,
64	}
65	
66	#[derive(Debug)]
67	pub(crate) struct ForgeReleaseOperation {
68	    pub(crate) tag: TagName,
69	    pub(crate) prerelease: bool,
70	    /// Derived from the changelog at execution; not part of the intent digest.
71	    pub(crate) notes: ReleaseNotes,
72	}
73	
74	/// The body a forge release is created with.
75	#[derive(Clone, Debug, PartialEq, Eq)]
76	pub(crate) enum ReleaseNotes {
77	    /// The package's changelog section for the released version.
78	    Section(String),
79	    /// The forge generates notes, because no changelog section is usable.
80	    Generated { reason: NotesFallback },
81	}
82	
83	/// Why a forge release falls back to generated notes.
84	#[derive(Clone, Copy, Debug, PartialEq, Eq, thiserror::Error)]
85	pub(crate) enum NotesFallback {
86	    #[error("no changelog configured")]
87	    NotConfigured,
88	    #[error("changelog file missing")]
89	    FileMissing,
90	    #[error("no section for this version")]
91	    SectionMissing,
92	    #[error("changelog section is empty")]
93	    SectionEmpty,
94	    #[error("changelog unreadable")]
95	    Unreadable,
96	}
97	
98	#[derive(Debug)]
99	pub(crate) struct ArtifactUploadOperation {
100	    pub(crate) slot: ArtifactSlotId,
101	    pub(crate) tag: TagName,
102	    pub(crate) prerelease: bool,
103	}
104	
105	#[derive(Debug)]
106	pub(crate) struct ForgePublishOperation {
107	    pub(crate) tag: TagName,
108	    pub(crate) prerelease: bool,
109	}
110	
111	/// What one pre-effect observation authorizes for an operation, carrying the
112	/// proof token the state machine requires to act on it.
113	#[derive(Debug)]
114	pub enum ReleasePreflight {
115	    /// The effect has not happened and may be issued.
116	    Proceed { proof: AbsentProof },
117	    /// The provider already holds exactly this operation's intended result.
118	    AlreadySatisfied { evidence: ExactEvidence },
119	}
120	
121	/// The executor's whole view of the outside world.
122	///
123	/// Keeping it this small is deliberate: a test set holding nothing but a map
124	/// of canned observations satisfies it, which is what makes the executor's
125	/// crash and convergence paths testable without a provider on `PATH`.
126	pub trait ReleaseProviderSet {
127	    /// The immutable intent every operation id must belong to.
128	    fn intent(&self) -> &ReleaseIntentV1;
129	
130	    /// Re-observes the held workspace immediately before an effect.
131	    fn recheck_trust(&self) -> Result<(), GraphError>;
132	
133	    /// The single fresh pre-effect observation for one operation, made before
134	    /// the executor persists `Attempting` so a failure here cannot strand the
135	    /// operation mid-flight.
136	    fn preflight(
137	        &self,
138	        id: &ReleaseOperationId,
139	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
140	    ) -> Result<ReleasePreflight, GraphError>;
141	
142	    /// A fresh observation of what the provider holds, with no effect.
143	    fn observe(
144	        &self,
145	        id: &ReleaseOperationId,
146	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
147	    ) -> Result<ProviderObservationV1, GraphError>;
148	
149	    /// Issues the one mutating action for this operation and confirms it.
150	    /// `proof` is only obtainable from an `Absent` pre-effect observation.
151	    fn publish(
152	        &self,
153	        permit: &ApplyPermit,
154	        proof: &AbsentProof,
155	        id: &ReleaseOperationId,
156	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
157	    ) -> Result<ExactEvidence, GraphError>;
158	}
159	
160	/// What one provider role can do.
161	///
162	/// `can_observe` means the role answers an observation at all, not that the
163	/// answer can be exact: PyPI answers `Indeterminate` because its upload
164	/// endpoint is not a query API, and that is still an answer the executor can
165	/// fail closed on.
166	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
167	pub(crate) struct ProviderCapabilities {
168	    pub(crate) can_observe: bool,
169	    pub(crate) can_publish: bool,
170	}
171	
172	/// The permit and the absence proof that together authorize one effect.
173	pub(crate) struct EffectAuthorization<'a> {
174	    pub(crate) permit: &'a ApplyPermit,
175	    #[allow(dead_code)] // a type-level token: holding it is the authorization
176	    pub(crate) proof: &'a AbsentProof,
177	}
178	
179	/// One operation's whole provider-visible input.
180	pub(crate) struct ProviderRequest<'a> {
181	    pub(crate) id: &'a ReleaseOperationId,
182	    pub(crate) operation: &'a PreparedOperation,
183	    pub(crate) artifacts: Option<&'a VerifiedArtifactManifest<'a>>,
184	}
185	
186	/// Everything a provider may touch outside its prepared operation.
187	pub(crate) struct ProviderContext<'a> {
188	    root: &'a Path,
189	    runner: &'a dyn CommandRunner,
190	    git_remote: Option<&'a PreparedGitRemote>,
191	    sleeper: &'a dyn policy::Sleeper,
192	}
193	
194	impl<'a> ProviderContext<'a> {
195	    pub(crate) fn new(
196	        root: &'a Path,
197	        runner: &'a dyn CommandRunner,
198	        git_remote: Option<&'a PreparedGitRemote>,
199	    ) -> Self {
200	        ProviderContext {
201	            root,
202	            runner,
203	            git_remote,
204	            sleeper: &policy::ThreadSleeper,
205	        }
206	    }
207	
208	    /// Replaces the wall-clock wait, so a test can exercise the retry schedule
209	    /// without spending it.
210	    #[cfg(test)]
211	    pub(crate) fn with_sleeper(mut self, sleeper: &'a dyn policy::Sleeper) -> Self {
212	        self.sleeper = sleeper;
213	        self
214	    }
215	
216	    pub(crate) fn root(&self) -> &'a Path {
217	        self.root
218	    }
219	
220	    pub(crate) fn runner(&self) -> &'a dyn CommandRunner {
221	        self.runner
222	    }
223	
224	    pub(crate) fn sleeper(&self) -> &'a dyn policy::Sleeper {
225	        self.sleeper
226	    }
227	
228	    pub(crate) fn checked_git_remote(&self) -> Result<&'a PreparedGitRemote, GraphError> {
229	        let expected = self.git_remote.ok_or(GraphError::ReleasePreconditionUnmet {
230	            requirement: ReleasePreconditionRequirement::GitRemotePrepared,
231	        })?;
232	        recheck_git_remote(self.root, self.runner, expected)?;
233	        Ok(expected)
234	    }
235	
236	    /// The checked remote's `owner/repo` slug.
237	    pub(crate) fn github_repository_slug(&self) -> Result<String, GraphError> {
238	        Ok(self
239	            .checked_git_remote()?
240	            .github_repository
241	            .as_ref()
242	            .ok_or(GraphError::ReleasePreconditionUnmet {
243	                requirement: ReleasePreconditionRequirement::GitHubRemote,
244	            })?
245	            .as_slug())
246	    }
247	}
248	
249	/// One operation role's adapter: what it can do, what it sees, what it does.
250	pub(crate) trait ReleaseProvider {
251	    fn capabilities(&self) -> ProviderCapabilities;
252	
253	    fn observe(
254	        &self,
255	        context: &ProviderContext<'_>,
256	        request: &ProviderRequest<'_>,
257	    ) -> Result<ProviderObservationV1, GraphError>;
258	
259	    /// Issues the one mutating action, then re-observes: the returned evidence
260	    /// is always a post-effect observation, never the client's own exit code.
261	    fn publish(
262	        &self,
263	        context: &ProviderContext<'_>,
264	        request: &ProviderRequest<'_>,
265	        effect: &EffectAuthorization<'_>,
266	    ) -> Result<ExactEvidence, GraphError>;
267	
268	    /// The disagreement this role reports when a pre-effect observation is
269	    /// neither absent nor exactly the intended result.
270	    fn preflight_conflict(&self) -> RemoteConflict;
271	
272	    fn preflight(
273	        &self,
274	        context: &ProviderContext<'_>,
275	        request: &ProviderRequest<'_>,
276	    ) -> Result<ReleasePreflight, GraphError> {
277	        preflight_from_observation(self.observe(context, request)?, request.id, self.preflight_conflict())
278	    }
279	}
280	
281	/// The one place a prepared operation is routed to the provider that performs
282	/// it. Roles are selected here; the registry role selects its per-ecosystem
283	/// adapter in [`registry::adapter_for`], which is the only other selection.
284	fn provider_for(operation: &PreparedOperation) -> &'static dyn ReleaseProvider {
285	    match operation {
286	        PreparedOperation::RegistryPublish(_) => &registry::RegistryProvider,
287	        PreparedOperation::Tag(_) => &tag::TagProvider,
288	        PreparedOperation::ForgeRelease(_) => &forge::ForgeReleaseProvider,
289	        PreparedOperation::ArtifactUpload(_) => &artifact::ArtifactUploadProvider,
290	        PreparedOperation::ForgePublish(_) => &forge::ForgePublishProvider,
291	    }
292	}
293	
294	/// A role that can issue an effect but cannot be asked what the provider holds
295	/// could never prove absence before acting, so it is refused here -- before any
296	/// observation or effect -- rather than at dispatch.
297	pub(crate) fn checked_provider_for(operation: &PreparedOperation) -> Result<&'static dyn ReleaseProvider, GraphError> {
298	    let provider = provider_for(operation);
299	    require_observable(provider.capabilities())?;
300	    Ok(provider)
301	}
302	
303	fn require_observable(capabilities: ProviderCapabilities) -> Result<(), GraphError> {
304	    if capabilities.can_publish && !capabilities.can_observe {
305	        return Err(GraphError::ReleasePreconditionUnmet {
306	            requirement: ReleasePreconditionRequirement::ObservableProvider,
307	        });
308	    }
309	    Ok(())
310	}
311	
312	/// Maps one observation to its pre-effect decision. `conflict` names the
313	/// operation-specific disagreement so the typed error stays precise.
314	pub(crate) fn preflight_from_observation(
315	    observation: ProviderObservationV1,
316	    id: &ReleaseOperationId,
317	    conflict: RemoteConflict,
318	) -> Result<ReleasePreflight, GraphError> {
319	    match &observation {
320	        ProviderObservationV1::Absent => Ok(ReleasePreflight::Proceed {
321	            proof: observation
322	                .absent_proof()
323	                .expect("an absent observation mints an absent proof"),
324	        }),
325	        ProviderObservationV1::Exact { .. } => Ok(ReleasePreflight::AlreadySatisfied {
326	            evidence: observation
327	                .exact_evidence()
328	                .expect("an exact observation mints its evidence"),
329	        }),
330	        ProviderObservationV1::Conflict { .. } => Err(GraphError::ReleaseRemoteConflict { conflict }),
331	        ProviderObservationV1::Indeterminate { .. } => Err(GraphError::ReleaseProviderIndeterminate {
332	            operation: Box::new(id.clone()),
333	        }),
334	    }
335	}
336	
337	/// Requires that a post-effect observation is exact before the operation may
338	/// be recorded as done.
339	pub(crate) fn confirmed_evidence(
340	    observation: ProviderObservationV1,
341	    id: &ReleaseOperationId,
342	    conflict: RemoteConflict,
343	) -> Result<ExactEvidence, GraphError> {
344	    match &observation {
345	        ProviderObservationV1::Exact { .. } => Ok(observation
346	            .exact_evidence()
347	            .expect("an exact observation mints its evidence")),
348	        ProviderObservationV1::Indeterminate { .. } => Err(GraphError::ReleaseProviderIndeterminate {
349	            operation: Box::new(id.clone()),
350	        }),
351	        ProviderObservationV1::Absent | ProviderObservationV1::Conflict { .. } => {
352	            Err(GraphError::ReleaseRemoteConflict { conflict })
353	        }
354	    }
355	}
356	
357	/// The invariant error a provider raises when it is handed another role's
358	/// prepared operation.
359	pub(crate) fn wrong_role(id: &ReleaseOperationId, expected: &str) -> GraphError {
360	    GraphError::ReleaseInvariant {
361	        detail: format!("operation `{id:?}` is not a prepared {expected} operation"),
362	    }
363	}
364	
365	#[cfg(test)]
366	mod tests {
367	    use super::*;
368	
369	    /// Every production role must be able to answer an observation, because
370	    /// the executor may only issue an effect against a proved absence.
371	    #[test]
372	    fn no_production_provider_can_publish_without_being_observable() {
373	        for provider in [
374	            &registry::RegistryProvider as &dyn ReleaseProvider,
375	            &tag::TagProvider,
376	            &forge::ForgeReleaseProvider,
377	            &artifact::ArtifactUploadProvider,
378	            &forge::ForgePublishProvider,
379	        ] {
380	            let capabilities = provider.capabilities();
381	            assert!(
382	                capabilities.can_observe,
383	                "a publishing provider that cannot observe would act without proof of absence"
384	            );
385	            assert!(capabilities.can_publish);
386	        }
387	    }
388	
389	    #[test]
390	    fn a_publish_only_role_is_refused_and_every_other_shape_is_allowed() {
391	        let error = require_observable(ProviderCapabilities {
392	            can_observe: false,
393	            can_publish: true,
394	        })
395	        .unwrap_err();
396	        assert!(
397	            matches!(
398	                error,
399	                GraphError::ReleasePreconditionUnmet {
400	                    requirement: ReleasePreconditionRequirement::ObservableProvider
401	                }
402	            ),
403	            "expected ReleasePreconditionUnmet(ObservableProvider), got {error:?}"
404	        );
405	        for capabilities in [
406	            ProviderCapabilities {
407	                can_observe: true,
408	                can_publish: true,
409	            },
410	            ProviderCapabilities {
411	                can_observe: true,
412	                can_publish: false,
413	            },
414	            ProviderCapabilities {
415	                can_observe: false,
416	                can_publish: false,
417	            },
418	        ] {
