1	//! The two forge roles: one draft GitHub release per prepared tag, and the
2	//! publication that closes it once every asset has been uploaded.
3	
4	use callisto_model::{
5	    ExactEvidence, ProviderConflictReason, ProviderEvidenceV1, ProviderIndeterminateCause, ProviderObservationV1,
6	    ReleasePackageId, TagName,
7	};
8	
9	use crate::error::{CommandFailure, RemoteConflict};
10	use crate::GraphError;
11	
12	use super::super::github::{github_release_for_tag, GitHubReleaseLookup};
13	use super::policy::{observe_until_visible, programs, timeouts};
14	use super::{
15	    confirmed_evidence, wrong_role, EffectAuthorization, ForgePublishOperation, ForgeReleaseOperation, NotesFallback,
16	    PreparedOperation, ProviderCapabilities, ProviderContext, ProviderRequest, ReleaseNotes, ReleaseProvider,
17	};
18	
19	pub(crate) struct ForgeReleaseProvider;
20	
21	impl ReleaseProvider for ForgeReleaseProvider {
22	    fn capabilities(&self) -> ProviderCapabilities {
23	        ProviderCapabilities {
24	            can_observe: true,
25	            can_publish: true,
26	        }
27	    }
28	
29	    fn preflight_conflict(&self) -> RemoteConflict {
30	        RemoteConflict::ForgeReleaseDiffers
31	    }
32	
33	    fn observe(
34	        &self,
35	        context: &ProviderContext<'_>,
36	        request: &ProviderRequest<'_>,
37	    ) -> Result<ProviderObservationV1, GraphError> {
38	        let operation = forge_operation(request)?;
39	        let repository = context.github_repository_slug()?;
40	        observed_forge_release(
41	            context,
42	            &operation.tag,
43	            operation.prerelease,
44	            &repository,
45	            Draft::Either,
46	        )
47	    }
48	
49	    fn publish(
50	        &self,
51	        context: &ProviderContext<'_>,
52	        request: &ProviderRequest<'_>,
53	        effect: &EffectAuthorization<'_>,
54	    ) -> Result<ExactEvidence, GraphError> {
55	        let operation = forge_operation(request)?;
56	        let repository = context.github_repository_slug()?;
57	        // Held until `gh` has read the file.
58	        let notes_dir;
59	        let notes_file = match &operation.notes {
60	            ReleaseNotes::Section(section) => {
61	                notes_dir = tempfile::tempdir().map_err(notes_file_error)?;
62	                let path = notes_dir.path().join("notes.md");
63	                callisto_model::atomic::atomic_write(&path, section, effect.permit).map_err(notes_file_error)?;
64	                Some(path.to_string_lossy().into_owned())
65	            }
66	            ReleaseNotes::Generated { reason } => {
67	                eprintln!("{}", generated_notes_notice(&request.id.package, *reason));
68	                None
69	            }
70	        };
71	        let create_args = release_create_args(operation, &repository, notes_file.as_deref());
72	        run_gh(context, &create_args, timeouts::FORGE_RELEASE_CREATE)?;
73	        confirmed_evidence(
74	            observe_until_visible(context.sleeper(), || {
75	                observed_forge_release(
76	                    context,
77	                    &operation.tag,
78	                    operation.prerelease,
79	                    &repository,
80	                    Draft::Either,
81	                )
82	            })?,
83	            request.id,
84	            RemoteConflict::ForgeReleaseNotObservedAfterCreate,
85	        )
86	    }
87	}
88	
89	/// `gh release create` for a draft: the changelog section when `notes_file` is set, else generated notes.
90	fn release_create_args<'a>(
91	    operation: &'a ForgeReleaseOperation,
92	    repository: &'a str,
93	    notes_file: Option<&'a str>,
94	) -> Vec<&'a str> {
95	    let mut args = vec![
96	        "release",
97	        "create",
98	        operation.tag.as_str(),
99	        "--repo",
100	        repository,
101	        "--verify-tag",
102	        "--draft",
103	    ];
104	    match notes_file {
105	        Some(path) => args.extend(["--notes-file", path]),
106	        None => args.push("--generate-notes"),
107	    }
108	    if operation.prerelease {
109	        args.push("--prerelease");
110	    }
111	    args
112	}
113	
114	fn generated_notes_notice(package: &ReleasePackageId, reason: NotesFallback) -> String {
115	    format!("notes: using generated notes ({reason}) for {package}")
116	}
117	
118	fn notes_file_error(error: std::io::Error) -> GraphError {
119	    GraphError::ReleaseInputRead {
120	        path: "notes.md".into(),
121	        message: error.to_string(),
122	    }
123	}
124	
125	pub(crate) struct ForgePublishProvider;
126	
127	impl ReleaseProvider for ForgePublishProvider {
128	    fn capabilities(&self) -> ProviderCapabilities {
129	        ProviderCapabilities {
130	            can_observe: true,
131	            can_publish: true,
132	        }
133	    }
134	
135	    fn preflight_conflict(&self) -> RemoteConflict {
136	        RemoteConflict::ForgeReleaseDiffers
137	    }
138	
139	    fn observe(
140	        &self,
141	        context: &ProviderContext<'_>,
142	        request: &ProviderRequest<'_>,
143	    ) -> Result<ProviderObservationV1, GraphError> {
144	        let operation = publish_operation(request)?;
145	        let repository = context.github_repository_slug()?;
146	        observed_forge_release(
