268	/// most one path per record (a rename or copy would otherwise emit two).
269	fn parse_raw_diff_z(raw: &str) -> Result<Vec<RawDiffEntry>, VcsError> {
270	    let mut entries = Vec::new();
271	    let mut tokens = raw.split('\0').filter(|token| !token.is_empty());
272	    while let Some(meta) = tokens.next() {
273	        let Some(meta) = meta.strip_prefix(':') else {
274	            return Err(VcsError::MalformedDiffOutput {
275	                detail: format!("unexpected token, expected a metadata line starting with `:`: {meta:?}"),
276	            });
277	        };
278	        let path = tokens.next().ok_or_else(|| VcsError::MalformedDiffOutput {
279	            detail: "truncated output: missing a path after its metadata line".to_string(),
280	        })?;
281	        let fields: Vec<&str> = meta.split(' ').collect();
282	        let [_old_mode, new_mode, _old_sha, new_sha, status_field] = fields.as_slice() else {
283	            return Err(VcsError::MalformedDiffOutput {
284	                detail: format!("malformed metadata line: {meta:?}"),
285	            });
286	        };
287	        let status = status_field
288	            .chars()
289	            .next()
290	            .ok_or_else(|| VcsError::MalformedDiffOutput {
291	                detail: format!("empty status in metadata line: {meta:?}"),
292	            })?;
293	        let new_mode = if status == 'D' {
294	            None
295	        } else {
296	            Some(
297	                u32::from_str_radix(new_mode, 8).map_err(|error| VcsError::MalformedDiffOutput {
298	                    detail: format!("invalid Git mode `{new_mode}`: {error}"),
299	                })?,
300	            )
301	        };
302	        entries.push(RawDiffEntry {
303	            path: path.to_string(),
304	            new_mode,
305	            new_sha: (*new_sha).to_string(),
306	            status,
307	        });
308	    }
309	    Ok(entries)
