650	/// Parses the `<RECORD_SEP>%H<FIELD_SEP>%B`-formatted `git log` output
651	/// produced by [`GitAccess::commits_since`] into [`GitCommit`]s, splitting
652	/// each raw message on its first blank line into `summary`/`body`.
653	fn parse_git_log_output(stdout: &str, cwd: &Path) -> Result<Vec<GitCommit>, VcsError> {
654	    let mut commits = Vec::new();
655	
656	    for record in stdout.split(RECORD_SEP) {
657	        // `tformat:`-style `--format=` output (the default when the format
658	        // string doesn't start with `format:`/`tformat:`) appends a
659	        // trailing newline after every entry; strip it rather than the
660	        // message's own content.
661	        let record = record.trim_end_matches('\n');
662	        if record.is_empty() {
663	            continue;
664	        }
665	
666	        let Some((sha_str, message)) = record.split_once(FIELD_SEP) else {
667	            return Err(VcsError::MalformedLogOutput {
668	                detail: format!(
669	                    "in `{}`: expected a `<sha>{FIELD_SEP:?}<message>` record, got: {record:?}",
670	                    cwd.display()
671	                ),
672	            });
673	        };
674	
675	        let sha = CommitSha::parse(sha_str).map_err(|e| VcsError::InvalidCommitSha {
676	            context: format!("in `git log` output in `{}`", cwd.display()),
677	            message: e.to_string(),
678	        })?;
679	
680	        let message = message.replace("\r\n", "\n");
681	        let (summary, body) = match message.split_once("\n\n") {
682	            Some((title, rest)) => (title.trim_end().to_string(), Some(rest.to_string())),
683	            None => (message.trim_end().to_string(), None),
684	        };
685	
686	        commits.push(GitCommit { sha, summary, body });
687	    }
688	
689	    Ok(commits)
690	}
