13	/// Fetches the full, unfiltered list of every tag name in the repository.
14	///
15	/// Deliberately fetches with no glob pattern: callers filter afterwards via
16	/// [`matching_tags`], so the fetch batches once across every package (see
17	/// [`TagIndex::build`]) instead of one `git` spawn per package.
18	pub(crate) fn fetch_all_tags(git: &GitAccess<'_>) -> Result<Vec<String>, GraphError> {
19	    let tags = git.list_tags(None)?;
20	    Ok(tags.into_iter().map(|t| t.as_str().to_string()).collect())
