23	/// Filters `all_tags` down to those matching `template`'s glob.
24	///
25	/// Compiles the glob via [`callisto_model::vcs::compile_tag_glob`] -- the same
26	/// helper `GitAccess::list_tags` uses -- so tag selection is identical
27	/// either way. Includes error behavior: a
28	/// `template.glob()` that fails to compile surfaces as
29	/// `Err(GraphError::Vcs(VcsError::InvalidGlob))` -- matching every tag is
30	/// the unsafe alternative, since a malformed template must never silently
31	/// make "last tag" resolution pick an unrelated package's tag.
32	fn matching_tags<'a>(all_tags: &'a [String], template: &TagTemplate) -> Result<Vec<&'a str>, GraphError> {
33	    let glob = template.glob();
34	    GLOB_COMPILE_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
35	    let matcher = callisto_model::vcs::compile_tag_glob(&glob).map_err(GraphError::Vcs)?;
36	
37	    Ok(all_tags
38	        .iter()
39	        .filter(|t| matcher.is_match(t.as_str()))
40	        .map(|s| s.as_str())
41	        .collect())
42	}
