72	/// string applies the identical template to every matching package, so
73	/// without this cache `TagIndex::build`'s per-package loop would recompile
74	/// the same `globset::Glob` and rescan the full tag list once per package
75	/// sharing that template, instead of once per distinct template.
76	fn select_from_tags_cached<'a>(
77	    all_tags: &'a [String],
78	    template: &TagTemplate,
79	    grammar: VersionGrammar,
80	    cache: &mut std::collections::HashMap<String, Vec<&'a str>>,
81	) -> Result<LastTagSelection, GraphError> {
82	    let glob = template.glob();
