94	/// E101 when a package's default template (`{name}@{version}`) is also another package's template.
95	fn reject_shared_default_templates<D: DependencyResolver>(graph: &D) -> Result<(), GraphError> {
96	    let mut by_template: BTreeMap<String, (bool, Vec<PackageId>)> = BTreeMap::new();
97	    for pkg in graph.packages() {
98	        let tmpl = pkg
99	            .tag_template
100	            .clone()
101	            .unwrap_or_else(|| TagTemplate::default_for(&pkg.id));
102	        let (has_default, ids) = by_template.entry(tmpl.as_str()).or_default();
103	        *has_default |= pkg.tag_template.is_none();
104	        ids.push(pkg.id.clone());
105	    }
106	    match by_template
107	        .into_iter()
108	        .find(|(_, (has_default, ids))| *has_default && ids.len() > 1)
109	    {
110	        Some((template, (_, packages))) => Err(GraphError::SharedDefaultTagTemplate { template, packages }),
111	        None => Ok(()),
112	    }
113	}
