1	//! Wall-clock and retry policy shared by every release provider.
2	
3	use std::path::Path;
4	use std::time::Duration;
5	
6	use callisto_model::{CommandError, CommandOutput, CommandRunner, ProviderObservationV1, Version};
7	
8	use crate::GraphError;
9	
10	/// Wall-clock deadlines for every command the release path issues. Without
11	/// them one hung provider consumes the whole CI job budget; a breach surfaces
12	/// as `CommandError::TimedOut` (E025) and, after `Attempting` is persisted,
13	/// fails closed exactly as any other dispatch error.
14	pub(crate) mod timeouts {
15	    use std::time::Duration;
16	
17	    /// `cargo publish`, `npm publish`, `python -m build`, `twine upload`.
18	    pub(crate) const PUBLISH: Duration = Duration::from_secs(900);
19	    /// The subprocess deadline around one registry query (`cargo info`, `npm view`, `curl` PyPI simple index).
20	    pub(crate) const REGISTRY_QUERY: Duration = Duration::from_secs(300);
21	    /// `gh attestation verify`.
22	    pub(crate) const ATTESTATION_VERIFY: Duration = Duration::from_secs(120);
23	    /// `gh api`.
24	    pub(crate) const FORGE_API: Duration = Duration::from_secs(60);
25	    /// `git ls-remote`.
26	    pub(crate) const GIT_LS_REMOTE: Duration = Duration::from_secs(60);
27	    /// `git push`.
28	    pub(crate) const GIT_PUSH: Duration = Duration::from_secs(120);
29	    /// `gh release create`.
30	    pub(crate) const FORGE_RELEASE_CREATE: Duration = Duration::from_secs(120);
31	    /// `gh release upload`.
32	    pub(crate) const FORGE_ASSET_UPLOAD: Duration = Duration::from_secs(600);
33	    /// Purely local git reads (`rev-parse`, `for-each-ref`, `remote get-url`).
34	    pub(crate) const LOCAL_GIT: Duration = Duration::from_secs(60);
35	}
36	
37	/// External programs and the remote name the release path invokes.
38	pub(crate) mod programs {
39	    pub(crate) const GIT: &str = "git";
40	    pub(crate) const GH: &str = "gh";
41	    pub(crate) const CARGO: &str = "cargo";
42	    pub(crate) const NPM: &str = "npm";
43	    /// The PyPI simple-index observation query (`curl -sS -i`).
44	    pub(crate) const CURL: &str = "curl";
45	    /// The remote whose push URL is the trusted release destination.
46	    pub(crate) const GIT_REMOTE: &str = "origin";
47	}
48	
49	/// Total tries for one read-only observation, including the first.
50	pub(crate) const OBSERVATION_MAX_ATTEMPTS: u32 = 5;
51	
52	/// Longest single wait, and the clamp applied to a server's `Retry-After`.
53	pub(crate) const OBSERVATION_BACKOFF_CAP: Duration = Duration::from_secs(300);
54	
55	/// Exponential backoff between observation attempts: 2s, 4s, 8s, 16s.
56	pub(crate) fn observation_backoff(attempt: u32) -> Duration {
57	    Duration::from_secs(2u64.saturating_pow(attempt + 1)).min(OBSERVATION_BACKOFF_CAP)
58	}
59	
60	/// GitHub's reads lag its writes by seconds; waits of 2s to 32s cover about a minute.
61	pub(crate) const EFFECT_VISIBILITY_ATTEMPTS: u32 = 6;
62	
63	/// Re-observes this run's own effect while it reads `Absent`; any other answer is final.
64	pub(crate) fn observe_until_visible(
65	    sleeper: &dyn Sleeper,
66	    mut observe: impl FnMut() -> Result<ProviderObservationV1, GraphError>,
67	) -> Result<ProviderObservationV1, GraphError> {
68	    let mut index = 0;
69	    loop {
70	        let observation = observe()?;
71	        if !matches!(observation, ProviderObservationV1::Absent) || index + 1 >= EFFECT_VISIBILITY_ATTEMPTS {
72	            return Ok(observation);
73	        }
74	        sleeper.sleep(observation_backoff(index));
75	        index += 1;
76	    }
77	}
78	
79	/// One attempt's result: either it settled the question, or it left the answer
80	/// unknown for a reason that may resolve on its own.
81	#[derive(Debug, PartialEq, Eq)]
82	pub(crate) enum Attempt<T> {
83	    Settled(T),
84	    /// `value` is the answer to report if every attempt is exhausted.
85	    Transient {
86	        value: T,
87	        retry_after: Option<Duration>,
88	    },
89	}
90	
91	/// The wall-clock wait, injected so tests exercise the schedule without it.
92	pub(crate) trait Sleeper: Sync {
93	    fn sleep(&self, duration: Duration);
94	}
95	
96	pub(crate) struct ThreadSleeper;
97	
98	impl Sleeper for ThreadSleeper {
99	    fn sleep(&self, duration: Duration) {
100	        std::thread::sleep(scaled_for_tests(duration));
101	    }
102	}
103	
104	/// Test-only, like cargo's `__CARGO_TEST_*`: e2e tests can't inject a `Sleeper`.
105	fn scaled_for_tests(duration: Duration) -> Duration {
106	    match std::env::var("__CALLISTO_TEST_SLEEP_SCALE") {
107	        Ok(raw) => match raw.parse::<f64>() {
108	            Ok(scale) if scale.is_finite() && scale >= 0.0 => duration.mul_f64(scale),
109	            _ => duration,
110	        },
111	        Err(_) => duration,
112	    }
113	}
114	
115	/// A command that could not be run at all (timed out or failed to spawn), unlike one that ran and exited non-zero.
116	#[derive(Debug)]
117	pub(crate) struct CommandUnavailable;
118	
119	/// Translates a timeout or I/O failure into `CommandUnavailable` so `retry_observation` can retry it, instead
120	/// of propagating a hard `GraphError`. `NotFound` stays a hard error: retrying can't install a missing program.
121	pub(crate) fn run_observation(
122	    runner: &dyn CommandRunner,
123	    program: &str,
124	    args: &[&str],
125	    cwd: &Path,
126	    timeout: Duration,
127	    quiet: bool,
128	) -> Result<Result<CommandOutput, CommandUnavailable>, GraphError> {
129	    let result = if quiet {
130	        runner.run_quiet(program, args, cwd, timeout)
131	    } else {
132	        runner.run_with_timeout(program, args, cwd, timeout)
133	    };
134	    match result {
135	        Ok(output) => Ok(Ok(output)),
136	        Err(CommandError::TimedOut { .. } | CommandError::Io { .. }) => Ok(Err(CommandUnavailable)),
137	        Err(other) => Err(other.into()),
138	    }
139	}
140	
141	/// The one bounded retry in the release path. It wraps read-only observations
142	/// only: an effect (publish, push, release create, asset upload) is never
143	/// re-issued from here, because a transient error cannot prove the first
144	/// attempt did not take effect.
145	pub(crate) fn retry_observation<T>(
146	    sleeper: &dyn Sleeper,
147	    mut attempt: impl FnMut() -> Result<Attempt<T>, GraphError>,
148	) -> Result<T, GraphError> {
149	    let mut exhausted = None;
150	    for index in 0..OBSERVATION_MAX_ATTEMPTS {
151	        match attempt()? {
152	            Attempt::Settled(value) => return Ok(value),
153	            Attempt::Transient { value, retry_after } => {
154	                exhausted = Some(value);
155	                if index + 1 < OBSERVATION_MAX_ATTEMPTS {
156	                    sleeper.sleep(
157	                        retry_after
158	                            .unwrap_or_else(|| observation_backoff(index))
159	                            .min(OBSERVATION_BACKOFF_CAP),
160	                    );
161	                }
162	            }
163	        }
164	    }
165	    Ok(exhausted.expect("at least one attempt always runs"))
166	}
167	
168	/// A successful publish-client exit isn't a receipt: confirms the registry
169	/// itself has caught up before treating the operation as done. If not, it
170	/// stays `Attempting` for reconciliation, reported via its own variant
171	/// rather than `ReleaseIntentStale`'s false "no operation was authorized".
172	pub(crate) fn require_registry_confirmation(
173	    is_published: bool,
174	    package: &str,
175	    version: &Version,
176	) -> Result<(), GraphError> {
177	    if is_published {
178	        return Ok(());
179	    }
180	    Err(GraphError::RegistryPublishUnconfirmed {
181	        package: package.to_string(),
182	        version: version.clone(),
183	    })
184	}
185	
186	#[cfg(test)]
187	pub(crate) mod tests {
188	    use super::*;
189	    use callisto_model::VersionGrammar;
190	    use std::collections::VecDeque;
191	    use std::sync::Mutex;
192	
193	    /// Hands back one scripted `run`/`run_quiet`/`run_with_timeout` result per call, in order.
194	    struct ScriptedCommand(Mutex<VecDeque<Result<CommandOutput, CommandError>>>);
195	
196	    impl ScriptedCommand {
197	        fn new(results: Vec<Result<CommandOutput, CommandError>>) -> Self {
198	            Self(Mutex::new(results.into()))
199	        }
200	    }
201	
202	    impl CommandRunner for ScriptedCommand {
203	        fn run(&self, _program: &str, _args: &[&str], _cwd: &std::path::Path) -> Result<CommandOutput, CommandError> {
204	            self.0.lock().unwrap().pop_front().expect("no more scripted results")
205	        }
206	    }
207	
208	    fn ok_output() -> CommandOutput {
209	        CommandOutput {
210	            exit_code: Some(0),
211	            stdout: String::new(),
212	            stderr: String::new(),
213	        }
214	    }
215	
216	    /// A timed-out command must become `CommandUnavailable`, not propagate as a hard `GraphError`.
217	    #[test]
218	    fn a_timed_out_command_is_unavailable_not_a_hard_error() {
219	        let runner = ScriptedCommand::new(vec![Err(CommandError::TimedOut {
220	            program: "cargo".to_string(),
221	            seconds: 300,
222	        })]);
223	        let result = run_observation(&runner, "cargo", &[], std::path::Path::new("."), Duration::ZERO, true);
224	        assert!(matches!(result, Ok(Err(CommandUnavailable))));
225	    }
226	
227	    #[test]
228	    fn an_io_failure_is_unavailable_not_a_hard_error() {
229	        let runner = ScriptedCommand::new(vec![Err(CommandError::Io {
230	            program: "git".to_string(),
231	            message: "broken pipe".to_string(),
232	        })]);
233	        let result = run_observation(&runner, "git", &[], std::path::Path::new("."), Duration::ZERO, false);
234	        assert!(matches!(result, Ok(Err(CommandUnavailable))));
235	    }
236	
237	    /// A missing program can never resolve by retrying, so it stays a hard error.
238	    #[test]
239	    fn a_missing_program_is_still_a_hard_error() {
240	        let runner = ScriptedCommand::new(vec![Err(CommandError::NotFound {
241	            program: "cargo".to_string(),
242	        })]);
243	        let result = run_observation(&runner, "cargo", &[], std::path::Path::new("."), Duration::ZERO, true);
244	        assert!(matches!(
245	            result,
246	            Err(GraphError::Command(CommandError::NotFound { .. }))
247	        ));
248	    }
249	
250	    #[test]
251	    fn a_successful_run_passes_the_output_through() {
252	        let runner = ScriptedCommand::new(vec![Ok(ok_output())]);
253	        let result = run_observation(&runner, "cargo", &[], std::path::Path::new("."), Duration::ZERO, true);
254	        assert_eq!(result.unwrap().unwrap(), ok_output());
255	    }
256	
257	    /// Composes `run_observation` with `retry_observation` so a command that times out once still retries and settles.
258	    #[test]
259	    fn a_write_not_yet_visible_is_observed_again_until_it_appears() {
260	        let sleeper = RecordingSleeper::new();
261	        let mut answers = vec![
262	            ProviderObservationV1::Absent,
263	            ProviderObservationV1::Absent,
264	            ProviderObservationV1::Indeterminate {
265	                cause: callisto_model::ProviderIndeterminateCause::CommandFailed,
266	            },
267	        ]
268	        .into_iter();
269	        let observed = observe_until_visible(&sleeper, || Ok(answers.next().unwrap())).unwrap();
270	        assert!(matches!(observed, ProviderObservationV1::Indeterminate { .. }));
271	        assert_eq!(sleeper.waits(), vec![Duration::from_secs(2), Duration::from_secs(4)]);
272	    }
273	
274	    #[test]
275	    fn a_write_that_never_appears_is_reported_absent_after_about_a_minute() {
276	        let sleeper = RecordingSleeper::new();
277	        let mut calls = 0;
278	        let observed = observe_until_visible(&sleeper, || {
279	            calls += 1;
280	            Ok(ProviderObservationV1::Absent)
281	        })
282	        .unwrap();
283	        assert!(matches!(observed, ProviderObservationV1::Absent));
284	        assert_eq!(calls, EFFECT_VISIBILITY_ATTEMPTS);
285	        assert_eq!(sleeper.waits().iter().sum::<Duration>(), Duration::from_secs(62));
286	    }
