288	    #[test]
289	    fn retry_observation_recovers_from_one_timed_out_attempt() {
290	        let runner = ScriptedCommand::new(vec![
291	            Err(CommandError::TimedOut {
292	                program: "cargo".to_string(),
293	                seconds: 300,
294	            }),
295	            Ok(ok_output()),
