297	        let sleeper = RecordingSleeper::new();
298	        let result = retry_observation(&sleeper, || {
299	            match run_observation(&runner, "cargo", &[], std::path::Path::new("."), Duration::ZERO, true)? {
300	                Ok(output) => Ok(Attempt::Settled(output)),
301	                Err(CommandUnavailable) => Ok(Attempt::Transient {
302	                    value: ok_output(),
303	                    retry_after: None,
304	                }),
