17	    ApplyPermit, ArtifactDigest, ArtifactManifestEntryV1, ArtifactManifestV1, ExecutionTrustProfileV1,
18	    GitHubArtifactAttestationV1, PackageId, ReleaseArtifactManifestReport, ReleaseDryRunReport, ReleaseExecuteReport,
19	    ReleaseIntentV1, ReleaseIntentV1Wire, ReleaseNothingReport, ReleasePackageId, ReleasePlanReport, ReleaseReceiptV1,
20	    ReleaseReport, ReleaseRunEnvelopeV1,
21	};
