24	    GlobalArgs, OutputFormat, ReleaseArgs, ReleaseArtifactManifestArgs, ReleaseCommandArgs, ReleaseExecuteArgs,
25	    ReleaseInspectArgs, ReleasePlanArgs,
26	};
