31	
32	pub fn handle(args: ReleaseCommandArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
33	    match args.command {
34	        None => release(&args.packages, args.receipt, global),
35	        Some(ReleaseArgs::Plan(args)) => plan(args, global),
36	        Some(ReleaseArgs::Inspect(args)) => inspect(args, global),
37	        Some(ReleaseArgs::ArtifactManifest(args)) => artifact_manifest(args, global),
38	        Some(ReleaseArgs::Execute(args)) => execute(args, global),
39	    }
40	}
41	
42	/// Stderr note when a preview's tags have no `origin` to push to.
43	pub const TAGS_UNBOUND_NOTE: &str =
44	    "note: `origin` has no push URL, so tag operations are unbound; `callisto release` will refuse until one is set";
45	
46	/// Exact stdout when no package has an unreleased version.
47	pub const NOTHING_TO_RELEASE: &str = "Nothing to release.";
48	
49	fn release(
50	    packages: &[String],
51	    receipt: Option<std::path::PathBuf>,
52	    global: &GlobalArgs,
53	) -> Result<ExitCode, CliError> {
54	    let selections = parse_selections(packages)?;
55	    let runner = CliCommandRunner;
56	    let workspace = load_workspace(global, &runner)?;
57	    let root = workspace.root.clone();
58	    let locator = IgnoreWalkLocator::new(&root);
59	    if global.dry_run {
60	        let plan = plan_local_release(&root, &locator, &runner, &selections, LocalReleaseSource::Preview)?;
61	        write_release_preview(plan.as_ref(), global.format, &mut std::io::stdout())?;
62	        return Ok(ExitCode::SUCCESS);
63	    }
64	    if let Some(route) = ci_release_route(&workspace)? {
65	        return Err(CliError::ReleaseRequiresCiRoute {
66	            reason: route.to_string(),
67	        });
68	    }
69	    let Some(plan) = plan_local_release(&root, &locator, &runner, &selections, LocalReleaseSource::Trusted)? else {
70	        print_nothing_to_release(global)?;
71	        return Ok(ExitCode::SUCCESS);
72	    };
73	    for diagnostic in &plan.diagnostics {
74	        eprintln!("warning: {}", diagnostic.message);
75	    }
76	    let intent = plan.intent;
77	    let permit = ApplyPermit::granted_unless_dry_run(global.dry_run).expect("non-dry-run permits writes");
78	    // A receipt records only full success; a partial run is recovered by rerunning.
79	    if let Some(path) = &receipt {
80	        callisto_model::atomic::probe_atomic_write(path, &permit).map_err(|source| CliError::Io {
81	            source,
82	            path: Some(path.clone()),
83	        })?;
84	    }
85	    let callisto_model::SourceIdentity::GitCommit { sha } = &intent.snapshot.source else {
86	        return Err(CliError::ReleaseEnvelopeInvalid {
87	            detail: "a local release source must be a Git commit".to_owned(),
88	        });
89	    };
90	    // A local run is its own orchestration, so both revisions are the source commit.
91	    let envelope =
92	        ReleaseRunEnvelopeV1::new(sha.clone(), &intent, None).map_err(|error| CliError::ReleaseEnvelopeInvalid {
93	            detail: error.to_string(),
94	        })?;
95	    let capability = validate_local_release_intent(&root, &locator, &runner, intent)?;
96	    let state = execute_release(&capability, &permit, &envelope, None)?;
97	    let receipt_document =
98	        ReleaseReceiptV1::from_state(capability.intent(), &state).map_err(|error| CliError::ReleaseReceiptIssue {
99	            detail: error.to_string(),
100	        })?;
101	    if let Some(path) = &receipt {
102	        write_receipt(path, &receipt_document, &permit)?;
103	    }
104	    match global.format {
105	        OutputFormat::Json => emit_report(
106	            &mut std::io::stdout(),
107	            &ReleaseReport {
108	                receipt: receipt_document.clone(),
109	            },
110	            global.dry_run,
111	        )?,
112	        OutputFormat::Text => {
113	            let released = capability.intent().decision.entries.len();
114	            match &receipt {
115	                Some(path) => emit_line(&format!(
116	                    "Released {released} package(s); receipt saved to {}",
117	                    path.display()
118	                ))?,
119	                None => emit_line(&format!("Released {released} package(s)"))?,
120	            }
121	        }
122	    }
123	    Ok(ExitCode::SUCCESS)
124	}
