214	        }
215	        callisto_model::ReleaseOperationRole::Tag => "create git tag".to_owned(),
216	        callisto_model::ReleaseOperationRole::ForgeRelease => "create GitHub release draft".to_owned(),
217	        callisto_model::ReleaseOperationRole::ArtifactUpload { slot } => {
