224	/// Human-readable plan: each package and version, then its operations.
225	///
226	/// `use_color` is the one color/table decision ([`crate::color::enabled`]):
227	/// box-drawing table formatting renders only alongside color, never independently.
228	fn render_release_plan(intent: &ReleaseIntentV1, use_color: bool) -> String {
229	    let mut out = String::from("Release plan:\n");
230	    if use_color {
231	        out.push_str(&render_release_plan_table(intent));
232	        return out;
233	    }
234	    for entry in &intent.decision.entries {
235	        out.push_str(&format!("  {} {}\n", entry.package, entry.target_version));
236	        for operation in intent.operations.iter().filter(|op| op.id().package == entry.package) {
237	            out.push_str(&format!("    - {}\n", describe_operation(operation)));
238	        }
239	    }
240	    out
