78	/// The single seam through which this executor changes state.
79	fn apply(
80	    state: &mut ReleaseExecutionStateV1,
81	    operation: &ReleaseOperationId,
82	    event: &OperationEvent,
83	) -> Result<(), GraphError> {
84	    state
85	        .apply(operation, event)
86	        .map(|_| ())
87	        .map_err(|source| match source {
88	            ReleaseStateError::EvidenceRejected(source) => GraphError::ReleaseProviderObservation { source },
89	            source => GraphError::ReleaseExecutionState { source },
90	        })
91	}
92	
93	/// Refuses to report success until every operation has an observed terminal
94	/// success state.
95	fn require_terminal_success(intent: &ReleaseIntentV1, state: &ReleaseExecutionStateV1) -> Result<(), GraphError> {
96	    let count = intent
97	        .operations
98	        .iter()
99	        .filter(|operation| {
100	            !state
101	                .operation_state(operation.id())
102	                .is_some_and(OperationState::is_success)
103	        })
104	        .count();
105	    if count == 0 {
106	        Ok(())
107	    } else {
108	        Err(GraphError::ReleaseIncomplete { count })
109	    }
110	}
111	
112	/// Requires the verification capability whenever `intent` declares compiled
113	/// binary slots. Its private constructor already proved both manifest binding
114	/// and local byte/attestation identity.
115	fn require_verified_artifact_manifest(
116	    intent: &ReleaseIntentV1,
117	    artifacts: Option<&VerifiedArtifactManifest<'_>>,
118	) -> Result<(), GraphError> {
119	    match (intent.artifact_slots.is_empty(), artifacts) {
120	        (true, None) => Ok(()),
121	        (true, Some(_)) => Err(GraphError::ReleaseInvariant {
122	            detail: "verified artifact manifest supplied for slot-less release intent".to_owned(),
123	        }),
124	        (false, Some(artifacts)) => require_artifact_manifest_matches_intent(intent, Some(artifacts.manifest())),
125	        (false, None) => Err(GraphError::ReleasePreconditionUnmet {
126	            requirement: ReleasePreconditionRequirement::VerifiedArtifactManifest,
127	        }),
128	    }
129	}
130	
131	/// Validates the serializable manifest independently of local byte and
132	/// attestation verification. Kept as a focused invariant helper for tests;
133	/// production execution requires `VerifiedArtifactManifest` above.
134	fn require_artifact_manifest_matches_intent(
135	    intent: &ReleaseIntentV1,
136	    artifacts: Option<&callisto_model::ArtifactManifestV1>,
137	) -> Result<(), GraphError> {
138	    match (intent.artifact_slots.is_empty(), artifacts) {
139	        (true, None) => Ok(()),
140	        (true, Some(manifest)) | (false, Some(manifest)) => manifest
141	            .validate_for_intent(intent)
142	            .map_err(|source| GraphError::ArtifactManifest { source }),
143	        (false, None) => Err(GraphError::ReleasePreconditionUnmet {
144	            requirement: ReleasePreconditionRequirement::ArtifactManifestProvided,
145	        }),
146	    }
147	}
148	
149	/// The pending operations whose every transitive prerequisite is exactly
150	/// `Published` or `AlreadySatisfied`, in the intent's canonical order.
151	pub(crate) fn eligible_operations(
152	    intent: &ReleaseIntentV1,
153	    state: &ReleaseExecutionStateV1,
154	) -> Vec<ReleaseOperationId> {
155	    let prerequisites: BTreeMap<_, _> = intent
156	        .operations
157	        .iter()
158	        .map(|operation| (operation.id().clone(), operation.prerequisites().to_vec()))
159	        .collect();
160	    let mut satisfied = BTreeMap::new();
161	    intent
162	        .operations
163	        .iter()
164	        .filter(|operation| state.operation_state(operation.id()) == Some(OperationState::Pending))
165	        .filter(|operation| {
166	            prerequisites_satisfied_transitively(
167	                operation.id(),
168	                &prerequisites,
169	                state,
170	                &mut BTreeSet::new(),
171	                &mut satisfied,
172	            )
173	        })
174	        .map(|operation| operation.id().clone())
175	        .collect()
176	}
177	
178	/// `satisfied` memoizes each subtree's answer, so the walk is linear in the DAG.
179	fn prerequisites_satisfied_transitively(
180	    id: &ReleaseOperationId,
181	    prerequisites: &BTreeMap<ReleaseOperationId, Vec<ReleaseOperationId>>,
182	    state: &ReleaseExecutionStateV1,
183	    on_path: &mut BTreeSet<ReleaseOperationId>,
184	    satisfied: &mut BTreeMap<ReleaseOperationId, bool>,
185	) -> bool {
186	    if let Some(known) = satisfied.get(id) {
187	        return *known;
188	    }
189	    // The intent is already a proven DAG; the on-path guard fails closed on a cycle anyway.
190	    if !on_path.insert(id.clone()) {
191	        return false;
192	    }
193	    let result = prerequisites.get(id).is_some_and(|direct| {
194	        direct.iter().all(|prerequisite| {
195	            state
196	                .operation_state(prerequisite)
197	                .is_some_and(OperationState::is_success)
198	                && prerequisites_satisfied_transitively(prerequisite, prerequisites, state, on_path, satisfied)
199	        })
200	    });
201	    on_path.remove(id);
202	    satisfied.insert(id.clone(), result);
203	    result
204	}
