        // forge operation.
        publish_operation(&mut state, &tag);
        assert_eq!(state.operation_state(&publish), Some(OperationState::Pending));
        let eligible = eligible_operations(&intent, &state);
        assert_eq!(eligible, [publish]);
        assert!(!eligible.contains(&forge));
    }

